<?php declare(strict_types=1);require_once __DIR__.'/../lib/app_layout.php';require_once __DIR__.'/../lib/module_helpers.php';$user=require_role(['admin','principal','clerk']);$s=db()->prepare('SELECT s.*,c.name class_name FROM students s LEFT JOIN classes c ON c.id=s.class_id AND c.school_id=s.school_id WHERE s.id=? AND s.school_id=?');$s->execute([(int)($_GET['id']??0),(int)$user['school_id']]);$student=$s->fetch();if(!$student){http_response_code(404);exit('सापडला नाही');}layout_start('विद्यार्थी माहिती','gr');?><div class="bg-white border rounded-2xl p-7 grid sm:grid-cols-2 gap-5"><?php foreach(['gr_no'=>'GR क्रमांक','first_name'=>'नाव','father_name'=>'वडिलांचे नाव','surname'=>'आडनाव','mother_name'=>'आईचे नाव','class_name'=>'वर्ग','roll_no'=>'हजेरी क्रमांक','dob'=>'जन्मतारीख','gender'=>'लिंग','phone'=>'फोन','address'=>'पत्ता','status'=>'स्थिती'] as $key=>$label):?><div><p class="text-sm text-slate-500"><?=e($label)?></p><p class="font-bold text-navy mt-1"><?=e((string)($student[$key]??'—'))?></p></div><?php endforeach;?></div><div class="mt-5 flex gap-3"><a class="bg-gold rounded-xl px-5 py-3 font-bold" href="/modules/gr/edit.php?id=<?=$student['id']?>">संपादन</a><a class="border rounded-xl px-5 py-3" href="/modules/gr/register_print.php?id=<?=$student['id']?>&print=1">नोंदणी प्रिंट</a></div><?php layout_end();?>
